import React, { useEffect, useState, useRef } from 'react';
import { CalendarClock, Building2, ClipboardCheck, DollarSign, Check, AlertCircle } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { useAuth } from '../../hooks/useAuth';
import { syncGoogleCalendar } from '../../lib/kairo';
import { Deal, INITIAL_DEAL_STAGE } from '../../types';
import { Button } from '../../components/ui/Button';
import { EmptyState } from '../../components/ui/EmptyState';
import { TopBar } from '../../components/layout/TopBar';
import { BottomSheet } from '../../components/ui/BottomSheet';
import { cn } from '../../lib/utils';

interface ScheduledMeeting {
  id: string;
  user_id: string;
  calendar_event_id: string;
  title: string | null;
  start_time: string | null;
  end_time: string | null;
  attendees: any | null;
  status: 'unassigned' | 'assigned' | 'completed';
  deal_id: string | null;
  created_at: string;
}

function formatMeetingTime(startTime: string | null): string {
  if (!startTime) return 'No time set';
  const date = new Date(startTime);
  return date.toLocaleString('en-US', {
    weekday: 'short',
    month: 'short',
    day: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
  });
}

export function Inbox() {
  const { user } = useAuth();
  const userRef = useRef(user);
  userRef.current = user;

  const [meetings, setMeetings] = useState<ScheduledMeeting[]>([]);
  const [deals, setDeals] = useState<Deal[]>([]);
  const [loading, setLoading] = useState(true);
  const [syncing, setSyncing] = useState(false);

  const [selectedMeeting, setSelectedMeeting] = useState<ScheduledMeeting | null>(null);

  const [mode, setMode] = useState<'existing' | 'new'>('existing');
  const [selectedDealId, setSelectedDealId] = useState('');
  const [newDealName, setNewDealName] = useState('');
  const [newCompanyName, setNewCompanyName] = useState('');
  const [newDealValue, setNewDealValue] = useState('');
  const [processing, setProcessing] = useState(false);
  const [error, setError] = useState('');

  useEffect(() => {
    if (!user) return;
    syncAndFetch();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  // Keeps the open Inbox page current without a manual reload: re-runs
  // fetchData() (not syncAndFetch()) whenever scheduled_meetings changes for
  // this user, so a write from any source -- this page's own assignment
  // actions, calendar sync from another tab, recording review write-back --
  // shows up immediately. Deliberately does NOT call syncGoogleCalendar()
  // here; this only reacts to rows already in the database, same scope as
  // the nav badge's subscription.
  useEffect(() => {
    if (!user) return;
    const uid = user.id;
    // Unique suffix, same reasoning as useInboxCount: a shared channel name
    // is a singleton in the Supabase client, so if this effect ever runs
    // twice concurrently for the same user (Strict Mode double-invoke in
    // dev, a fast route re-mount), the second `.channel()` call would return
    // the first's already-subscribed channel and its `.on()` calls would
    // throw. A random suffix guarantees each mount gets its own channel.
    const channelId = Math.random().toString(36).slice(2);

    const channel = supabase
      .channel(`inbox-page-${uid}-${channelId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'scheduled_meetings', filter: `user_id=eq.${uid}` },
        () => {
          if (userRef.current?.id === uid) {
            fetchData(uid);
          }
        }
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [user]);

  async function syncAndFetch() {
    setLoading(true);
    await syncCalendar();
    await fetchData();
    setLoading(false);
  }

  async function syncCalendar() {
    if (!userRef.current) return;
    setSyncing(true);
    // If the user hasn't connected a calendar, syncGoogleCalendar just
    // no-ops -- that's fine, we simply won't have upcoming meetings to show.
    await syncGoogleCalendar();
    setSyncing(false);
  }

  async function fetchData(targetUserId?: string) {
    const currentUserId = targetUserId || userRef.current?.id;
    if (!currentUserId) return;
    // Both unassigned AND assigned meetings are shown here -- assigned ones
    // just render with a green "Assigned" button instead of a purple
    // "Assign" one. Cancelled meetings are excluded, and so are 'completed'
    // ones: completed meetings that have already been reviewed belong on that
    // deal's own review/timeline, not here.
    // Without this filter a completed meeting's status no longer matches
    // 'assigned', so it would render as a stale, clickable "Assign" card
    // instead of disappearing.
    const [{ data: allMeetings }, { data: dealsData }] = await Promise.all([
      supabase
        .from('scheduled_meetings')
        .select('*')
        .eq('user_id', currentUserId)
        .in('status', ['unassigned', 'assigned'])
        .is('cancelled_at', null)
        .order('start_time', { ascending: true }),
      supabase
        .from('deals')
        .select('*')
        .eq('user_id', currentUserId)
        .eq('status', 'active')
        .order('updated_at', { ascending: false }),
    ]);
    setMeetings(allMeetings || []);
    setDeals(dealsData || []);
  }

  function openMeeting(meeting: ScheduledMeeting) {
    if (meeting.status === 'assigned') return;
    setSelectedMeeting(meeting);
    resetSheetState();
  }

  function resetSheetState() {
    setMode('existing');
    setSelectedDealId('');
    setNewDealName('');
    setNewCompanyName('');
    setNewDealValue('');
    setError('');
  }

  function closeSheet() {
    setSelectedMeeting(null);
    resetSheetState();
  }

  // Assigning an upcoming meeting to a deal -- no transcript exists yet,
  // no AI review runs. This links the meeting to a deal.
  // No stage is set here for the existing-deal path -- the deal simply
  // keeps whatever stage it's already at until its next call is reviewed
  // and Kairo infers the stage from what actually happened.
  async function handleAssignMeeting(e: React.FormEvent) {
    e.preventDefault();
    if (!user || !selectedMeeting) return;

    if (mode === 'existing' && !selectedDealId) {
      setError('Select a deal to assign this meeting to.');
      return;
    }
    if (mode === 'new' && (!newDealName.trim() || !newCompanyName.trim())) {
      setError('Deal name and company name are required.');
      return;
    }

    setProcessing(true);
    setError('');

    let dealId = selectedDealId;
    let createdDealId: string | null = null;

    try {
      if (mode === 'new') {
        const parsedValue = newDealValue.trim() ? Number(newDealValue.replace(/[,$]/g, '')) : null;

        const { data: deal, error: dealError } = await supabase
          .from('deals')
          .insert({
            user_id: user.id,
            deal_name: newDealName.trim(),
            company_name: newCompanyName.trim(),
            deal_stage: INITIAL_DEAL_STAGE,
            deal_value: parsedValue,
            status: 'active',
            risk_level: 'none',
          })
          .select()
          .single();

        if (dealError || !deal) throw new Error('Failed to create deal.');
        dealId = deal.id;
        createdDealId = deal.id;
      }

      const { error: updateError } = await supabase
        .from('scheduled_meetings')
        .update({
          deal_id: dealId,
          status: 'assigned',
          updated_at: new Date().toISOString(),
        })
        .eq('id', selectedMeeting.id);

      if (updateError) throw new Error('Failed to assign meeting.');

      closeSheet();
      fetchData();
    } catch (err: any) {
      if (createdDealId) {
        await supabase.from('deals').delete().eq('id', createdDealId);
      }
      setError(err.message || 'Something went wrong.');
    } finally {
      setProcessing(false);
    }
  }

  return (
    <>
      <div className="-mx-4 md:hidden">
        <TopBar title="Inbox" />
      </div>

      <div className="animate-fade-in">
        <div className="mb-6 hidden md:block">
          <h1 className="text-2xl font-display font-bold text-textPrimary mb-2">Inbox</h1>
          <p className="text-textSecondary text-sm">
            Assign upcoming meetings to a deal now — Kairo reviews the call automatically once it happens.
          </p>
        </div>

        {loading ? (
          <div className="space-y-2">
            {[1, 2, 3].map(i => <div key={i} className="card h-20 animate-pulse" />)}
          </div>
        ) : meetings.length === 0 ? (
          <EmptyState
            icon={<CalendarClock className="w-6 h-6" />}
            title={syncing ? 'Syncing your calendar…' : 'No meetings yet'}
            description="Connect your calendar in Settings, or check back once you've scheduled your next call."
          />
        ) : (
          <div className="space-y-2">
            {meetings.map(meeting => {
              const isAssigned = meeting.status === 'assigned';
              return (
                <div
                  key={meeting.id}
                  className="card flex items-center gap-3 px-4 py-3 min-h-[64px]"
                >
                  <div className="w-8 h-8 rounded-lg bg-primary/8 border border-primary/15 flex items-center justify-center flex-shrink-0">
                    <CalendarClock className="w-4 h-4 text-primary" />
                  </div>
                  <div className="flex-1 min-w-0">
                    <p className="text-textPrimary text-sm font-medium truncate">
                      {meeting.title || 'Untitled meeting'}
                    </p>
                    <p className="text-textMuted text-xs mt-0.5">
                      {formatMeetingTime(meeting.start_time)}
                    </p>
                  </div>
                  {isAssigned ? (
                    <Button
                      type="button"
                      size="sm"
                      variant="secondary"
                      disabled
                      className="flex-shrink-0 !bg-transparent !border-emerald-500 !text-emerald-400 !opacity-100 disabled:!opacity-100 disabled:cursor-default"
                    >
                      <Check className="w-3.5 h-3.5" />
                      Assigned
                    </Button>
                  ) : (
                    <Button
                      type="button"
                      size="sm"
                      variant="secondary"
                      onClick={() => openMeeting(meeting)}
                      className="flex-shrink-0 !bg-transparent !border-primary !text-primary hover:!bg-primary/8"
                    >
                      <ClipboardCheck className="w-3.5 h-3.5" />
                      Assign
                    </Button>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </div>

      {/* Assign sheet */}
      <BottomSheet
        open={!!selectedMeeting}
        onClose={closeSheet}
        title="Assign Meeting"
      >
        {selectedMeeting && (
          <>
            <p className="text-textSecondary text-sm mb-4 truncate">
              {selectedMeeting.title || 'Untitled meeting'}
            </p>

            <div className="flex gap-2 mb-5">
              <button
                type="button"
                onClick={() => setMode('existing')}
                className={cn(
                  'flex-1 text-xs font-medium px-3 py-2.5 rounded-lg border transition-colors min-h-[44px]',
                  mode === 'existing'
                    ? 'bg-primary/8 border-primary/30 text-primary'
                    : 'border-border text-textMuted'
                )}
              >
                Existing Deal
              </button>
              <button
                type="button"
                onClick={() => setMode('new')}
                className={cn(
                  'flex-1 text-xs font-medium px-3 py-2.5 rounded-lg border transition-colors min-h-[44px]',
                  mode === 'new'
                    ? 'bg-primary/8 border-primary/30 text-primary'
                    : 'border-border text-textMuted'
                )}
              >
                New Deal
              </button>
            </div>

            <form onSubmit={handleAssignMeeting} className="space-y-4">
              {mode === 'existing' ? (
                <div>
                  <label className="block text-xs font-medium text-textSecondary mb-1.5">Deal</label>
                  <select
                    value={selectedDealId}
                    onChange={e => setSelectedDealId(e.target.value)}
                    className="input-field"
                  >
                    <option value="">Select a deal</option>
                    {deals.map(deal => (
                      <option key={deal.id} value={deal.id}>
                        {deal.deal_name} — {deal.company_name}
                      </option>
                    ))}
                  </select>
                </div>
              ) : (
                <>
                  <div>
                    <label className="block text-xs font-medium text-textSecondary mb-1.5">
                      Deal Name
                    </label>
                    <div className="relative">
                      <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                      <input
                        type="text"
                        value={newDealName}
                        onChange={e => setNewDealName(e.target.value)}
                        placeholder="e.g. Acme Corp — Enterprise Plan"
                        className="input-field pl-10"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-textSecondary mb-1.5">
                      Company Name
                    </label>
                    <div className="relative">
                      <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                      <input
                        type="text"
                        value={newCompanyName}
                        onChange={e => setNewCompanyName(e.target.value)}
                        placeholder="e.g. Acme Corp"
                        className="input-field pl-10"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs font-medium text-textSecondary mb-1.5">
                      Deal Value <span className="text-textMuted">(optional)</span>
                    </label>
                    <div className="relative">
                      <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                      <input
                        type="text"
                        inputMode="decimal"
                        value={newDealValue}
                        onChange={e => setNewDealValue(e.target.value)}
                        placeholder="e.g. 25000"
                        className="input-field pl-10"
                      />
                    </div>
                  </div>
                </>
              )}

              {error && (
                <div className="flex items-center gap-2 bg-red-400/10 border border-red-400/20 rounded-lg px-3 py-2">
                  <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0" />
                  <p className="text-red-400 text-xs">{error}</p>
                </div>
              )}

              <Button type="submit" className="w-full" size="lg" loading={processing} disabled={processing}>
                Assign Meeting
              </Button>
            </form>
          </>
        )}
      </BottomSheet>
    </>
  );
}