import React, { useEffect, useRef, useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowRight, Building2, FileText, AlertCircle, DollarSign, Calendar, CheckCircle2, X, Mic } from 'lucide-react';
import { supabase } from '../../lib/supabase';
import { reviewCall, saveDealState, saveStakeholders, resolveDealStage, checkCalendarConnected, syncGoogleCalendar, GOOGLE_CALENDAR_URL } from '../../lib/kairo';
import { useAuth } from '../../hooks/useAuth';
import { useSubscription } from '../../hooks/useSubscription';
import { Button } from '../../components/ui/Button';
import { LoadingState } from '../../components/ui/LoadingState';
import { TopBar } from '../../components/layout/TopBar';
import { RecordCallScreen } from '../../components/record/RecordCallScreen';
import { UpgradeModal } from '../../components/ui/UpgradeModal';
import { INITIAL_DEAL_STAGE } from '../../types';
import { cn } from '../../lib/utils';

type Step = 'deal' | 'transcript' | 'record' | 'awaiting-meeting' | 'scheduled';

// Tailwind's `md` breakpoint -- used once, at click time, to decide whether
// "Schedule First Meeting" waits for a success screen (desktop) or just
// sends the user to Dashboard on return (mobile). See handleScheduleFirstMeeting.
const DESKTOP_MEDIA_QUERY = '(min-width: 768px)';

// How long we let a "Schedule First Meeting" click wait for the event to
// show up as assigned before giving up quietly. Desktop-only -- see
// handleScheduleFirstMeeting for why mobile doesn't use this at all.
const AWAIT_MEETING_TIMEOUT_MS = 20_000;
const AWAIT_MEETING_POLL_MS = 1500;

export function NewDeal() {
  const navigate = useNavigate();
  const location = useLocation();
  const { user, profile } = useAuth();
  const { canWrite } = useSubscription(user?.id);
  const [showUpgradeModal, setShowUpgradeModal] = useState(false);
  const [step, setStep] = useState<Step>('deal');
  const [dealName, setDealName] = useState('');
  const [companyName, setCompanyName] = useState('');
  const [dealValue, setDealValue] = useState('');
  const [transcript, setTranscript] = useState('');
  const [analyzing, setAnalyzing] = useState(false);
  const [error, setError] = useState('');

  // Set once "Schedule First Meeting" successfully creates the deal, so the
  // transcript step (if the user backs out and picks Upload First Call
  // instead) reuses the same deal row rather than creating a second one.
  // Also set when navigated here from DealReview's "Add a Call" empty-state
  // (via route state.existingDealId) -- in that case the deal already exists
  // and must never be deleted on unmount regardless of outcome.
  const [scheduledDealId, setScheduledDealId] = useState<string | null>(null);
  const scheduledDealIdRef = useRef<string | null>(null);
  const [calendarConnected, setCalendarConnected] = useState<boolean | null>(null);
  const [showConnectPrompt, setShowConnectPrompt] = useState(false);
  const [creatingDeal, setCreatingDeal] = useState(false);
  const awaitingReturn = useRef(false);
  // Mobile takes a different path on return than desktop (straight to
  // Dashboard, no success screen) -- see handleScheduleFirstMeeting.
  const awaitingReturnIsMobile = useRef(false);
  const pollTimeoutRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pollIntervalRef = useRef<ReturnType<typeof setInterval> | null>(null);

  // Tracks whether a call was successfully submitted so the unmount cleanup
  // knows NOT to delete the deal. Starts false; set to true only in the
  // success paths of handleSubmit and handleRecordingComplete.
  const callSucceeded = useRef(false);

  // True when the deal row was created by a pre-existing deal (navigated
  // here from DealReview empty-state). We must NEVER delete it on unmount --
  // it has other data (stakeholders, deal_state) that we didn't create.
  const dealIsPreexisting = useRef(false);

  // Bootstrap from route state when DealReview's "Add a Call" empty-state
  // navigates here with an existing dealId. Jump straight to the transcript
  // step so the user doesn't have to re-enter deal info or create a new row.
  useEffect(() => {
    const state = location.state as { existingDealId?: string } | null;
    if (state?.existingDealId) {
      setScheduledDealId(state.existingDealId);
      scheduledDealIdRef.current = state.existingDealId;
      dealIsPreexisting.current = true;
      setStep('transcript');
    }
    // location.state is stable for the lifetime of this mount -- only run once.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  useEffect(() => {
    if (!user) return;
    checkCalendarConnected(user.id).then(setCalendarConnected);
  }, [user]);

  useEffect(() => {
    return () => {
      if (pollTimeoutRef.current) clearTimeout(pollTimeoutRef.current);
      if (pollIntervalRef.current) clearInterval(pollIntervalRef.current);
    };
  }, []);

  // Orphan-deal cleanup: if we created a deal row but the user navigates
  // away before a call was successfully submitted, delete the empty deal
  // so it doesn't clutter the dashboard. Skip if the deal was pre-existing
  // (navigated here from DealReview) -- we don't own that row.
  useEffect(() => {
    return () => {
      const dealIdToDelete = scheduledDealIdRef.current;
      if (dealIdToDelete && !callSucceeded.current && !dealIsPreexisting.current) {
        // Best-effort fire-and-forget -- no UI to report errors to at this point.
        supabase.from('deals').delete().eq('id', dealIdToDelete);
      }
    };
  }, []);


  function clearPolling() {
    if (pollTimeoutRef.current) { clearTimeout(pollTimeoutRef.current); pollTimeoutRef.current = null; }
    if (pollIntervalRef.current) { clearInterval(pollIntervalRef.current); pollIntervalRef.current = null; }
  }

  // The only reliable signal that a meeting actually got scheduled: a
  // scheduled_meetings row assigned to this deal. syncGoogleCalendar()
  // itself returns void, so after triggering a sync we poll the table
  // directly rather than trusting that the fetch alone means success.
  async function checkForAssignedMeeting(dealId: string): Promise<boolean> {
    const { data } = await supabase
      .from('scheduled_meetings')
      .select('id')
      .eq('deal_id', dealId)
      .eq('status', 'assigned')
      .limit(1)
      .maybeSingle();
    return !!data;
  }

  // Desktop only. Shows the "waiting on your meeting" screen, then the
  // success screen once the scheduled_meetings row shows up assigned, or
  // quietly falls back to the deal step if nothing turns up in time.
  function beginAwaitingMeeting(dealId: string) {
    setStep('awaiting-meeting');

    pollIntervalRef.current = setInterval(async () => {
      const found = await checkForAssignedMeeting(dealId);
      if (found) {
        clearPolling();
        setStep('scheduled');
      }
    }, AWAIT_MEETING_POLL_MS);

    pollTimeoutRef.current = setTimeout(() => {
      clearPolling();
      // No assigned meeting turned up in time -- the user either didn't
      // finish scheduling or made an event with no video link. Return
      // quietly to deal info; the deal itself is already saved.
      setStep('deal');
    }, AWAIT_MEETING_TIMEOUT_MS);
  }

  // Fires when the user comes back to this tab after Google Calendar opened.
  // Desktop: sync, check for the assigned meeting, show success or fall
  // back to deal info (the existing, working desktop behavior -- unchanged).
  // Mobile: skip all of that entirely and just go to Dashboard. Mobile
  // browsers don't reliably fire `focus` the same way desktop tabs do, so
  // rather than chase that detection, mobile doesn't wait for a signal at
  // all here -- it goes straight to Dashboard as soon as the user is back.
  useEffect(() => {
    async function handleFocus() {
      if (!awaitingReturn.current) return;
      const isMobile = awaitingReturnIsMobile.current;
      awaitingReturn.current = false;
      awaitingReturnIsMobile.current = false;

      if (isMobile) {
        navigate('/app/dashboard');
        return;
      }

      await syncGoogleCalendar();
      const currentDealId = scheduledDealIdRef.current ?? scheduledDealId;
      if (currentDealId) {
        const found = await checkForAssignedMeeting(currentDealId);
        if (found) {
          clearPolling();
          setStep('scheduled');
        }
        // If not found yet, the background poll (already running) keeps
        // checking until AWAIT_MEETING_TIMEOUT_MS.
      }
    }
    window.addEventListener('focus', handleFocus);
    return () => window.removeEventListener('focus', handleFocus);
  }, [scheduledDealId, navigate]);

  async function createDealRow(): Promise<string | null> {
    if (!user) return null;
    const parsedValue = dealValue.trim() ? Number(dealValue.replace(/[,$]/g, '')) : null;

    const { data: deal, error: dealError } = await supabase
      .from('deals')
      .insert({
        user_id: user.id,
        deal_name: dealName.trim(),
        company_name: companyName.trim(),
        deal_stage: INITIAL_DEAL_STAGE,
        deal_value: parsedValue,
        status: 'active',
        risk_level: 'none',
      })
      .select()
      .single();

    if (dealError || !deal) {
      setError('Failed to create deal.');
      return null;
    }
    return deal.id;
  }

  // "Schedule First Meeting" -- only does anything if calendar is connected.
  // If it's not, this is a no-op other than surfacing the connect prompt;
  // no deal gets created and nothing opens.
  //
  // Desktop and mobile diverge after the deal is created: desktop shows an
  // "awaiting meeting" screen and then a success screen once the meeting
  // shows up assigned (see beginAwaitingMeeting / the focus handler above).
  // Mobile skips all of that -- no waiting screen, no success screen, no
  // detection of whether the meeting was actually created -- it just sends
  // the user straight to Dashboard as soon as they're back in Kairo.
  async function handleScheduleFirstMeeting() {
    if (!canWrite) { setShowUpgradeModal(true); return; }
    if (!calendarConnected) {
      setShowConnectPrompt(true);
      return;
    }
    if (!user) return;

    setError('');
    setCreatingDeal(true);

    const dealId = scheduledDealIdRef.current ?? scheduledDealId ?? await createDealRow();

    if (!dealId) {
      setCreatingDeal(false);
      return;
    }
    setScheduledDealId(dealId);
    scheduledDealIdRef.current = dealId;

    // Best-effort -- if this write fails the user still reaches Google
    // Calendar, they'd just need to assign the meeting manually afterward.
    await supabase.from('pending_schedule_intents').insert({ user_id: user.id, deal_id: dealId });

    const isMobile = typeof window.matchMedia === 'function'
      ? !window.matchMedia(DESKTOP_MEDIA_QUERY).matches
      : true;

    awaitingReturn.current = true;
    awaitingReturnIsMobile.current = isMobile;

    setCreatingDeal(false);
    window.open(GOOGLE_CALENDAR_URL, '_blank', 'noopener,noreferrer');

    if (!isMobile) {
      beginAwaitingMeeting(dealId);
    }
    // Mobile: nothing else to do here. The focus handler above takes it
    // from here and navigates to Dashboard as soon as the user returns.
  }

  function handleUploadFirstCall(e: React.FormEvent) {
    e.preventDefault();
    if (!dealName.trim() || !companyName.trim()) return;
    if (!canWrite) { setShowUpgradeModal(true); return; }
    setStep('transcript');
  }

  function handleRecordNow() {
    if (!dealName.trim() || !companyName.trim()) return;
    if (!canWrite) { setShowUpgradeModal(true); return; }
    setError('');
    setStep('record');
  }

  // Passed to RecordCallScreen as `createDeal` -- only invoked on Stop,
  // reusing scheduledDealId if "Schedule First Meeting" already created
  // this deal earlier in the same visit, same pattern handleSubmit uses.
  async function handleCreateDealForRecording(): Promise<string | null> {
    if (scheduledDealIdRef.current) return scheduledDealIdRef.current;
    if (scheduledDealId) return scheduledDealId;
    const dealId = await createDealRow();
    if (dealId) {
      setScheduledDealId(dealId);
      scheduledDealIdRef.current = dealId;
    }
    return dealId;
  }

  function handleRecordingComplete(result: { conversationId: string; dealId: string }) {
    callSucceeded.current = true;
    navigate(`/app/deals/${result.dealId}/calls/${result.conversationId}`);
  }

  async function handleSubmit(e: React.FormEvent) {
    e.preventDefault();
    if (!user) return;
    if (!canWrite) { setShowUpgradeModal(true); return; }

    const text = transcript.trim();

    if (!text) { setError('Please paste a transcript before reviewing.'); return; }
    if (text.length < 100) { setError('Transcript is too short.'); return; }
    if (text.length > 50000) { setError('Transcript is too long.'); return; }

    setAnalyzing(true);
    setError('');

    let dealId: string | null = scheduledDealIdRef.current ?? scheduledDealId;
    let createdDealHere = false;

    try {
      if (!dealId) {
        dealId = await createDealRow();
        if (!dealId) throw new Error('Failed to create deal.');
        createdDealHere = true;
        setScheduledDealId(dealId);
        scheduledDealIdRef.current = dealId;
      }

      // First call for this deal: call-review still produces the full
      // deal-shaped extraction (call + deal halves) -- there's no separate
      // "first call" code path on the frontend, the AI handles that
      // distinction internally based on previous_review being null.
      const review = await reviewCall(text, {
        deal_name: dealName.trim(),
        company_name: companyName.trim(),
        deal_stage: INITIAL_DEAL_STAGE,
        previous_review: null,
        seller_context: {
          what_you_sell: profile?.what_you_sell || undefined,
          who_you_are: profile?.who_you_are || undefined,
        },
      });

      // Stage is now fully automatic: resolveDealStage reads
      // review.deal.suggested_deal_stage (what call-review concretely
      // observed happened) and applies it if it advances the deal past
      // INITIAL_DEAL_STAGE, or promotes straight to Closed Won/Lost on an
      // unambiguous close -- even on a brand-new deal's very first call.
      // Resolved BEFORE the conversations insert so deal_stage on that row
      // is the stage this call resulted in, matching the live deals.deal_stage
      // that Call Review reads -- see the matching comment in Review.tsx's
      // handleAddCall for why this ordering matters for Deal Activity.
      const resolvedStage = resolveDealStage(INITIAL_DEAL_STAGE, review);

      const { data: conv, error: convError } = await supabase
        .from('conversations')
        .insert({
          user_id: user.id,
          deal_id: dealId,
          deal_stage: resolvedStage,
          input_type: 'transcript',
          transcript: text,
          status: 'complete',
          analysis_json: review,
        })
        .select()
        .single();

      if (convError || !conv) throw new Error('Failed to save conversation.');

      // Deal Review needs data starting at call 1, not just call 2+.
      // review.deal is already the complete current-state extraction --
      // write it straight to deal_state, no aggregation step.
      await saveDealState(dealId, user.id, review, resolvedStage);
      await saveStakeholders(dealId, user.id, review);

      callSucceeded.current = true;
      navigate(`/app/deals/${dealId}/calls/${conv.id}`);

    } catch (err: any) {
      // Only delete the deal if we created it in this submission -- a deal
      // that already existed (created earlier via Schedule First Meeting)
      // must survive a failed transcript review.
      if (dealId && createdDealHere) {
        await supabase.from('deals').delete().eq('id', dealId);
      }
      setError(err.message || 'Something went wrong. Please try again.');
      setAnalyzing(false);
    }
  }

  if (analyzing) {
    return (
      <div className="min-h-[calc(100vh-64px)]">
        <LoadingState phase="analyzing" />
      </div>
    );
  }

  if (step === 'record') {
    return (
      <RecordCallScreen
        dealId={scheduledDealId || undefined}
        createDeal={handleCreateDealForRecording}
        onComplete={handleRecordingComplete}
        onClose={() => setStep('deal')}
      />
    );
  }

  if (step === 'awaiting-meeting') {
    return (
      <div className="animate-fade-in">
        <div className="-mx-4 md:hidden">
          <TopBar title="Scheduling" />
        </div>
        <div className="min-h-[calc(100vh-64px)] md:min-h-[calc(100vh-160px)] flex items-center justify-center px-4">
          <div className="flex flex-col items-center text-center max-w-xs">
            <div className="relative mb-8">
              <div className="w-14 h-14 rounded-full border-2 border-border flex items-center justify-center">
                <div className="w-10 h-10 rounded-full border-2 border-t-primary border-r-transparent border-b-transparent border-l-transparent animate-spin" />
              </div>
            </div>
            <p className="text-textPrimary font-semibold font-display text-lg mb-2">
              Waiting for your meeting
            </p>
            <p className="text-textSecondary text-sm">
              Finish scheduling in Google Calendar, then come back here. Kairo will pick it up automatically.
            </p>
          </div>
        </div>
      </div>
    );
  }

  if (step === 'scheduled') {
    return (
      <div className="animate-fade-in">
        <div className="-mx-4 md:hidden">
          <TopBar title="Deal Created" />
        </div>
        <div className="min-h-[calc(100vh-64px)] md:min-h-[calc(100vh-160px)] flex items-center justify-center px-4">
          <div className="w-full max-w-sm">
            <div className="card p-8 flex flex-col items-center text-center">
              <div className="w-16 h-16 rounded-2xl bg-primary/10 border border-primary/20 flex items-center justify-center mb-6">
                <CheckCircle2 className="w-8 h-8 text-primary" />
              </div>
              <h1 className="text-2xl font-display font-bold text-textPrimary mb-2">
                {dealName} is on the board
              </h1>
              <p className="text-textSecondary text-sm leading-relaxed mb-8">
                Your first meeting with {companyName} is on the calendar. Kairo will start building the deal review as soon as the call happens.
              </p>
              <Button size="lg" className="w-full" onClick={() => navigate('/app/dashboard')}>
                Go to Dashboard
                <ArrowRight className="w-4 h-4" />
              </Button>
            </div>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="animate-fade-in max-w-xl">
      {/* Mobile: TopBar handles back nav + title */}
      <div className="-mx-4 md:hidden">
        <TopBar
          title={step === 'deal' ? 'New Deal' : 'Add Transcript'}
          onBack={step === 'transcript' ? () => setStep('deal') : () => navigate(-1)}
        />
      </div>

      <div className="mb-6 md:mb-8">
        {/* Desktop-only back button, shown only on the transcript sub-screen */}
        <div className="hidden md:block">
          {step === 'transcript' && (
            <button
              onClick={() => setStep('deal')}
              className="flex items-center gap-1.5 text-textMuted hover:text-textPrimary text-xs mb-4 transition-colors"
            >
              <ArrowRight className="w-3.5 h-3.5 rotate-180" /> Back
            </button>
          )}

          <h1 className="text-2xl font-display font-bold text-textPrimary mb-1">
            {step === 'deal' ? 'New Deal' : 'Add Transcript'}
          </h1>
          <p className="text-textSecondary text-sm">
            {step === 'deal'
              ? 'Start by naming the deal, then schedule the first call or upload one you already had.'
              : 'Paste the call transcript. Kairo will review the deal and identify what matters most.'
            }
          </p>
        </div>

        {/* Mobile: title/subtitle only, no step indicator */}
        <p className="text-textSecondary text-sm mt-3 md:hidden">
          {step === 'deal'
            ? 'Start by naming the deal, then schedule the first call or upload one you already had.'
            : 'Paste the call transcript. Kairo will review the deal and identify what matters most.'
          }
        </p>
      </div>

      {step === 'deal' && (
        <form onSubmit={handleUploadFirstCall} className="space-y-4">
          <div className="card p-4 md:p-6 space-y-4">
            <div>
              <label className="block text-xs font-medium text-textSecondary mb-1.5">
                Deal Name <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                <input
                  type="text"
                  value={dealName}
                  onChange={e => setDealName(e.target.value)}
                  placeholder="e.g. Acme Corp — Enterprise Plan"
                  className="input-field pl-10"
                  required
                  autoFocus
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-textSecondary mb-1.5">
                Company Name <span className="text-red-500">*</span>
              </label>
              <div className="relative">
                <Building2 className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                <input
                  type="text"
                  value={companyName}
                  onChange={e => setCompanyName(e.target.value)}
                  placeholder="e.g. Acme Corp"
                  className="input-field pl-10"
                  required
                />
              </div>
            </div>

            <div>
              <label className="block text-xs font-medium text-textSecondary mb-1.5">
                Deal Value <span className="text-textMuted">(optional)</span>
              </label>
              <div className="relative">
                <DollarSign className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-textMuted" />
                <input
                  type="text"
                  inputMode="decimal"
                  value={dealValue}
                  onChange={e => setDealValue(e.target.value)}
                  placeholder="e.g. 25000"
                  className="input-field pl-10"
                />
              </div>
            </div>
          </div>

          {error && (
            <div className="flex gap-2 bg-red-400/10 border border-red-400/20 rounded-lg px-4 py-3">
              <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
              <p className="text-red-400 text-xs">{error}</p>
            </div>
          )}

          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            <Button
              type="button"
              variant="secondary"
              size="lg"
              className="w-full"
              disabled={!dealName.trim() || !companyName.trim() || creatingDeal}
              loading={creatingDeal}
              onClick={handleScheduleFirstMeeting}
            >
              <Calendar className="w-4 h-4" />
              Schedule First Meeting
            </Button>
            <Button
              type="submit"
              size="lg"
              className="w-full"
              disabled={!dealName.trim() || !companyName.trim()}
            >
              <FileText className="w-4 h-4" />
              Upload First Call
            </Button>
          </div>

          <div className="flex items-center gap-3">
            <div className="flex-1 h-px bg-border" />
            <span className="text-textMuted text-xs">or</span>
            <div className="flex-1 h-px bg-border" />
          </div>

          <div className="flex flex-col items-center gap-2 pt-1 pb-2">
            <button
              type="button"
              onClick={handleRecordNow}
              disabled={!dealName.trim() || !companyName.trim()}
              aria-label="Record call now"
              className="w-16 h-16 rounded-full bg-primary hover:bg-primaryLight text-white flex items-center justify-center shadow-purple-glow transition-all active:scale-95 disabled:opacity-40 disabled:cursor-not-allowed disabled:active:scale-100"
            >
              <Mic className="w-6 h-6" />
            </button>
            <p className="text-textMuted text-xs">Record Now</p>
          </div>

          {showConnectPrompt && (
            <div className="flex items-start gap-2 bg-amber-400/10 border border-amber-400/20 rounded-lg px-4 py-3 animate-fade-in">
              <Calendar className="w-4 h-4 text-amber-400 flex-shrink-0 mt-0.5" />
              <div className="flex-1 min-w-0">
                <p className="text-textPrimary text-xs font-medium mb-0.5">Google Calendar isn't connected</p>
                <p className="text-textSecondary text-xs leading-relaxed mb-2">
                  Connect your calendar in Settings to schedule the first meeting from here. For now, you can still upload a call you already had.
                </p>
                <button
                  type="button"
                  onClick={() => navigate('/app/settings')}
                  className="text-primary text-xs font-semibold"
                >
                  Go to Settings →
                </button>
              </div>
              <button
                type="button"
                onClick={() => setShowConnectPrompt(false)}
                className="text-textMuted flex-shrink-0"
                aria-label="Dismiss"
              >
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
          )}
        </form>
      )}

      {step === 'transcript' && (
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="card p-4 md:p-6 space-y-4">
            <div className="flex items-center gap-3 pb-4 border-b border-border">
              <div className="w-8 h-8 rounded-lg bg-primary/8 border border-primary/15 flex items-center justify-center flex-shrink-0">
                <Building2 className="w-4 h-4 text-primary" />
              </div>
              <div className="flex-1 min-w-0">
                <p className="text-textPrimary text-sm font-medium truncate">{dealName}</p>
                <p className="text-textMuted text-xs">{companyName}</p>
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-1.5">
                <label className="block text-xs font-medium text-textSecondary">Transcript</label>
                {transcript.length > 0 && (
                  <span className={cn(
                    'text-xs',
                    transcript.length > 50000 ? 'text-red-400 font-semibold' :
                    transcript.length > 40000 ? 'text-amber-400 font-medium' : 'text-textMuted'
                  )}>
                    {transcript.length.toLocaleString()} / 50,000 chars
                  </span>
                )}
              </div>
              <textarea
                value={transcript}
                onChange={e => setTranscript(e.target.value)}
                placeholder={`Paste your call transcript here.\n\nRep: Thanks for taking the time today...\nProspect: Of course...\n\nInclude speaker labels for better analysis.`}
                className="input-field min-h-56 md:min-h-64 resize-y font-mono text-xs leading-relaxed"
                autoFocus
              />
              <p className="text-xs text-textMuted mt-1.5">
                {transcript.length > 0
                  ? `${transcript.trim().split(/\s+/).filter(Boolean).length} words`
                  : 'Include speaker labels (Rep: / Prospect:) for best results'
                }
              </p>
            </div>
          </div>

          {error && (
            <div className="flex gap-2 bg-red-400/10 border border-red-400/20 rounded-lg px-4 py-3">
              <AlertCircle className="w-4 h-4 text-red-400 flex-shrink-0 mt-0.5" />
              <p className="text-red-400 text-xs">{error}</p>
            </div>
          )}

          <Button type="submit" size="lg" className="w-full" disabled={!transcript.trim()}>
            <FileText className="w-4 h-4" />
            Review Deal
          </Button>
        </form>
      )}

      <UpgradeModal open={showUpgradeModal} onClose={() => setShowUpgradeModal(false)} />
    </div>
  );
}