import { useState, useEffect, useCallback } from 'react';
import { supabase } from '../lib/supabase';

// Count of scheduled meetings still needing assignment -- i.e. Inbox cards
// that haven't turned green yet. Used by Sidebar and BottomNav to show a
// notification badge on the Inbox nav item. Each consumer calls this
// independently (same pattern as useAuth/useSubscription elsewhere) rather
// than threading the count through props.
//
// Kept in sync via a Realtime subscription on scheduled_meetings (filtered
// to this user), rather than polling -- any INSERT/UPDATE/DELETE re-runs the
// same count query. This makes the badge reflect whatever wrote to that
// table (calendar sync, recording review write-back, the Inbox page's own
// assignment actions, etc.) immediately, from any tab. This does NOT
// trigger a Google Calendar pull -- it only reacts to rows already in the
// database.
export function useInboxCount(userId: string | undefined) {
  const [count, setCount] = useState(0);

  const fetchCount = useCallback(async (uid: string) => {
    const { count: meetingsCount } = await supabase
      .from('scheduled_meetings')
      .select('id', { count: 'exact', head: true })
      .eq('user_id', uid)
      .eq('status', 'unassigned')
      .is('cancelled_at', null);
    setCount(meetingsCount || 0);
  }, []);

  useEffect(() => {
    if (!userId) {
      setCount(0);
      return;
    }

    fetchCount(userId);

    // Channel name includes a random suffix, not just userId: this hook is
    // called independently by both Sidebar and BottomNav for the same user
    // at the same time. Supabase treats a channel name as a singleton key --
    // two `.channel()` calls with the identical name return the SAME
    // underlying channel object, so the second caller's `.on()` registrations
    // land on a channel the first caller already `.subscribe()`d, which
    // throws ("cannot add postgres_changes callbacks ... after subscribe()").
    // A unique name per hook instance gives each consumer its own channel.
    const channelId = Math.random().toString(36).slice(2);
    const channel = supabase
      .channel(`inbox-count-${userId}-${channelId}`)
      .on(
        'postgres_changes',
        { event: '*', schema: 'public', table: 'scheduled_meetings', filter: `user_id=eq.${userId}` },
        () => fetchCount(userId)
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [userId, fetchCount]);

  return count;
}